input.command:
cat > migrations/002_tags.sql <<'EOF'
CREATE TABLE tags (
  id BIGSERIAL PRIMARY KEY,
  name TEXT NOT NULL UNIQUE
);

CREATE TABLE bookmark_tags (
  bookmark_id BIGINT NOT NULL REFERENCES bookmarks(id) ON DELETE CASCADE,
  tag_id BIGINT NOT NULL REFERENCES tags(id) ON DELETE CASCADE,
  PRIMARY KEY (bookmark_id, tag_id)
);

CREATE INDEX bookmark_tags_tag_id_idx ON bookmark_tags (tag_id);
EOF
cat > src/tags.ts <<'EOF'
import { sql } from './db';

export type TagCount = { id: string; name: string; bookmark_count: number };

// count(*) is bigint, which postgres.js returns as a string; cast to int so it is a number.
export function listTags() {
  return sql<TagCount[]>`
    select t.id, t.name, count(bt.bookmark_id)::int as bookmark_count
    from tags t
    left join bookmark_tags bt on bt.tag_id = t.id
    group by t.id, t.name
    order by bookmark_count desc, t.name`;
}
EOF
npm run check 2>&1 | tail -5

